\label{fact:baire}
Let $Y$ be a Polish space and $f\colon Y\to\mathbb{R}$ a function. The following are
equivalent:
\begin{enumerate}[label=\textup{(\arabic*)}]
\item the function $f$ is Baire-1;
\item for every open $U\subseteq\mathbb{R}$, the set $f^{-1}[U]$ is $F_\sigma$;
\item for every closed $F\subseteq Y$, the restriction $f|_F$ has a point of
continuity.
\end{enumerate}
Moreover, if $f$ is not Baire-1, then there are countable sets
$D_0,D_1\subseteq Y$ with $\overline{D_0}=\overline{D_1}$ and reals $a<b$ such
that $f\le a$ on $D_0$ and $f\ge b$ on $D_1$.

\label{lem:relcompact}
Let $Y$ be a Polish space and $\mathcal R\subseteqB_1(Y)$ a pointwise bounded
family. The following are equivalent:
\begin{enumerate}[label=\textup{(\roman*)}]
\item the family $\mathcal R$ is relatively compact in $B_1(Y)$;
\item every countable subset of $\mathcal R$ has an accumulation point in
$B_1(Y)$;
\item we have $\overline{\mathcal R}\subseteqB_1(Y)$.
\end{enumerate}

\label{thm:dichotomy}
Let $Y$ be a compact metrizable space and $\mathcal R\subseteqC_p(Y)$ a pointwise
bounded family. Then exactly one of the following holds:
\begin{enumerate}[label=\textup{(\roman*)}]
\item we have $\overline{\mathcal R}\subseteqB_1(Y)$;
\item the family $\mathcal R$ has the independence property.
\end{enumerate}

\label{thm:NIPclasses}
Let $Y$ be a compact metrizable space and $\{r_n:n\in\mathbb{N}\}\subseteqC_p(Y)$ a
pointwise bounded NIP family. Then exactly one of the following holds:
\begin{enumerate}[label=\textup{(\roman*)}]
\item the family is NIP$_3$;
\item the family is NIP$_2$ but not NIP$_3$, and there is an increasing
injection $\varphi\colon2^{<\mathbb{N}}\to\mathbb{N}$ such that $\{r_{\varphi(t)}\}$ is
equivalent to $D_3$ or to $D_4$;
\item the family is NIP$_1$ but not NIP$_2$, and there is an increasing
injection $\varphi$ such that $\{r_{\varphi(t)}\}$ is equivalent to $D_6$ or
to $D_7$;
\item the family is not NIP$_1$, and there is an increasing injection
$\varphi$ such that $\{r_{\varphi(t)}\}$ is equivalent to $D_5$.
\end{enumerate}

\label{def:NIP-observable}
An observable $C$ on $H_1\otimes H_2$ is \emph{NIP for Alice's responses} if
the response family $\mathcal R_C$ is NIP.

\label{prop:stable-metrizable}
Every stable observable is NIP$_3$: its idealized responses form a compact
metrizable space.

\label{thm:observable-classes}
Let $C$ be an observable on $H_1\otimes H_2$ that is NIP for Alice's
responses, and let $(\rho_n)$ be a trace-norm dense sequence in $\mathfrak D(H_1)$.
Then exactly one of the following holds:
\begin{enumerate}[label=\textup{(\roman*)}]
\item the observable $C$ is NIP$_3$;
\item the observable $C$ is NIP$_1$ but not NIP$_2$, and there is an
increasing injection $\varphi\colon2^{<\mathbb{N}}\to\mathbb{N}$ such that the responses
$\{r_{\rho_{\varphi(t)}}:t\in2^{<\mathbb{N}}\}$ are equivalent to $D_6$ or to $D_7$;
\item the observable $C$ is not NIP$_1$, and there is an increasing injection
$\varphi$ such that these responses are equivalent to $D_5$.
\end{enumerate}

\label{prop:fringes}
The fringe observable is not NIP: Alice's states $e_n$ form an independent
sequence, and the closure of their responses contains a copy of $\beta\mathbb{N}$.

\label{thm:hepta-natural}
Each minimal family is realized by a tree of actual preparations of a
physically natural observable: there are pure states $(\rho_t)_{t\in2^{<\mathbb{N}}}$
of Alice's system, given by pairwise orthogonal vectors, such that the responses $\{r_{\rho_t}\}$ are equivalent to
$D_i$, as follows.
\begin{enumerate}[label=\textup{(\arabic*)},leftmargin=*]
\item[$D_1$:] the comparison of photon numbers, with Alice's number states in
any order;
\item[$D_2$:] scanning, with Alice's chains $e_{s_t}$, whose scanning functions
are $s_t^\frown0^\infty$, for $s_t\in R$;
\item[$D_3$:] the comparison of positions, with Alice's particle spread over
the gap of $C_0$ immediately to the right of $\psi(s_t^\frown0^\infty)$;
\item[$D_4$:] the comparison of positions, with Alice's particle spread over
the gap of $C_0$ immediately to the left of $\psi(s_t^\frown1^\infty)$;
\item[$D_5$:] template matching, with Alice's chains $e_t$;
\item[$D_6$:] the combined observable, with Alice's chains $e_t$;
\item[$D_7$:] the comparison of positions, with Alice's particle spread half
over a short interval just to the left of $I_{s_t}$ and half over a short
interval just to the right of it.
\end{enumerate}
Moreover, the causal order of spacetime realizes $D_5$ in the sense of
Theorem~\ref{thm:causal}.

\label{lem:ssb-closure}
Let $\beta>0$ be given, and write $m^*=m^*(\beta)$. For $a\in[-1,1]$ and
$c\in[-m^*,m^*]$, let $g_{a,c}\colon Y\to\mathbb{R}$ be given by $g_{a,c}(h)=p'(h-a)$ for
$h\ne a$ and $g_{a,c}(a)=c$. Then the following hold:
\begin{enumerate}[label=\textup{(\roman*)}]
\item every $g_{a,c}$ with $-1<a<1$ belongs to $\overline\mathcal R$;
\item every function in $\overline\mathcal R\setminus\mathcal R$ equals $g_{a,c}$ for some
$a\in[-1,1]$ and $c\in[-m^*,m^*]$.
\end{enumerate}

\label{prop:qLY}
For every $N$, the function $Z_N$ is entire, $Z_N(h)\ne0$ whenever
$\operatorname{Re}h\ne0$, and $|Z_N(h)|\le Z_N(\operatorname{Re}h)$.

\label{prop:qanalytic}
The pressure $p$ is real analytic on $\mathbb{R}\setminus\{0\}$, and $m_N(h)\to p'(h)$ for
every $h\ne0$.
